cd ~/ctf/project; echo "import configparser, socket

def get_key(vault_id):
    cfg = configparser.ConfigParser()
    cfg.read('config.ini')
    s = socket.create_connection(('127.0.0.1', 31337))
    f = s.makefile('rw')
    banner = f.readline()
    f.write(f'AUTH {cfg['vault']['passphrase']}
')
    f.flush()
    response = f.readline()
    if response.strip() == 'OK':
        # TODO(v3): key request changed, see server banner
        return f.readline().strip()
    else:
        raise Exception(f'Unexpected response: {response}')" > vaultctl.py

